CREATE TABLE email_labels (label_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,color VARCHAR(20) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,PRIMARY KEY(label_id),UNIQUE KEY uq_email_labels_user_name(user_id,name),CONSTRAINT fk_email_labels_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE email_custom_folders (folder_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,color VARCHAR(20) NOT NULL,display_order INT NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,PRIMARY KEY(folder_id),UNIQUE KEY uq_email_folders_user_name(user_id,name),CONSTRAINT fk_email_folders_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE email_mailbox_entries ADD COLUMN custom_folder_id BIGINT UNSIGNED NULL,ADD KEY idx_email_mailbox_custom_folder(user_id,custom_folder_id),ADD CONSTRAINT fk_email_mailbox_custom_folder FOREIGN KEY(custom_folder_id) REFERENCES email_custom_folders(folder_id) ON DELETE SET NULL;
CREATE TABLE email_message_labels (message_label_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,message_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,label_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(message_label_id),UNIQUE KEY uq_email_message_label(message_id,user_id,label_id),KEY idx_email_message_labels_user_label(user_id,label_id),CONSTRAINT fk_email_message_labels_message FOREIGN KEY(message_id) REFERENCES email_messages(message_id) ON DELETE CASCADE,CONSTRAINT fk_email_message_labels_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,CONSTRAINT fk_email_message_labels_label FOREIGN KEY(label_id) REFERENCES email_labels(label_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
